from datetime import date
from decimal import Decimal
from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator

class SettlementRow(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True, populate_by_name=True, extra="ignore")

    order_id: str = Field(alias="Order ID", min_length=5)
    posted: date = Field(alias="Posted Date")
    amount: Decimal = Field(alias="Amount")
    refund: Decimal | None = Field(default=None, alias="Refund")

    @field_validator("amount", "refund", mode="before")
    @classmethod
    def clean_money(cls, v):
        if isinstance(v, str):
            v = v.replace(",", "").replace("$", "").strip()
            return v or None          # "" -> None
        return v

    @model_validator(mode="after")
    def refund_not_bigger(self):
        if self.refund is not None and abs(self.refund) > abs(self.amount):
            raise ValueError("refund exceeds amount")
        return self

